//    (email или «שירות המערכת (מפתח שירות)» / «SQL ישיר · <role>» / «לא נרשם (נשמרה לפני תיעוד המבצע)»);
//  - FL-39 «שינוי תצורה שאינו תקין נחסם לפני השמירה»: неизвестная модель → ошибка у поля «מזהה המודל», запрос не уходит;
//    сервер: admin_set_provider_config с неизвестной моделью → 400 unknown_model, версия не появляется.
// Роль admin (Super Admin). Версии НЕ сохраняются: форма блокирует запрос, RPC отклоняется сервером.
// На случай регресса (сервер принял бы модель) язык — свободный тестовый код q?? (как first-config-message), he/en/ar/ru не трогаются.
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';
import { openWithApi, runStamp, Api } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const TAG = '#e8e2be · #6a993d6db539691958e8e2be';
const FORBIDDEN_LANGS = ['he', 'en', 'ar', 'ru'];
const EXECUTOR = /@|שירות המערכת \(מפתח שירות\)|SQL ישיר · |לא נרשם \(נשמרה לפני תיעוד המבצע\)/;

type Cfg = { language: string; capability?: string; model?: string };

async function listConfigs(api: Api): Promise<Cfg[]> {
  const res = await api.rpc('admin_list_provider_configs');
  expect(res.status(), await res.text()).toBe(200);
  return (await res.json()) as Cfg[];
}

function unusedLang(configs: Cfg[]): string {
  const used = new Set(configs.map((r) => r.language.trim().toLowerCase()));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  for (let i = 0; i < 200; i++) {
    const code = 'q' + letters[Math.floor(Math.random() * 20)] + letters[Math.floor(Math.random() * 26)];
    if (!used.has(code) && !FORBIDDEN_LANGS.includes(code)) return code;
  }
  throw new Error('Не нашлось свободного тестового кода языка q??');
}

const history = (page: Page) => page.getByRole('region', { name: 'היסטוריית גרסאות' });

test.describe(`AI-провайдеры — исполнитель версии и неизвестная модель (${TAG})`, () => {
  test(`AC5: в «היסטוריית גרסאות» у каждой версии есть исполнитель, «—» нет; в «ספקים פעילים» «—» нет @desktop @prod-safe ${TAG}`, async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/admin/providers');
    const rows = history(page).getByRole('row').filter({ has: page.getByRole('cell') });
    await expect(rows.first(), 'история версий пуста').toBeVisible();

    // Источник: AC5 «נשמרים מבצע השינוי ומועדו»; реджект 21.10 — версии 18.10 с «—».
    const count = await rows.count();
    const bad: string[] = [];
    for (let i = 0; i < count; i++) {
      const cells = await rows.nth(i).getByRole('cell').allInnerTexts();
      const saved = (cells[cells.length - 1] ?? '').trim(); // колонка «נשמרה»: дата + исполнитель
      if (cells.some((c) => c.trim() === '—') || !EXECUTOR.test(saved)) bad.push(`${i + 1}: ${cells.map((c) => c.replace(/\s+/g, ' ').trim()).join(' | ')}`);
    }
    expect(bad, 'версии без исполнителя').toEqual([]);

    // Версии 18.10 (soniox/stt-async-v5, openai/gpt-realtime-2.1) — исполнитель приписан Super Admin (created_via sql:owner-backfill).
    const oct18 = rows.filter({ hasText: '18.10.2026' });
    const n18 = await oct18.count();
    for (let i = 0; i < n18; i++) await expect(oct18.nth(i)).toContainText('@');

    const active = page.getByRole('region', { name: 'ספקים פעילים' });
    if (await active.count()) await expect(active.getByText('—', { exact: true })).toHaveCount(0);
  });

  test(`FL-39: неизвестная модель в форме → ошибка у «מזהה המודל», запрос сохранения не уходит @desktop ${TAG}`, async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const api = await openWithApi(page, '/admin/providers');
    const lang = unusedLang(await listConfigs(api));
    const model = `qa-auto-e8e2be-${runStamp()}-nonexistent`;

    const saves: string[] = [];
    page.on('request', (r) => {
      if (r.method() === 'POST' && /\/rpc\/(admin|svc)_set_provider_config|\/functions\/v1\/save-provider-config/.test(r.url())) saves.push(r.url());
    });

    const form = page.getByRole('region', { name: 'הגדרת ספק' });
    await form.getByRole('combobox', { name: 'יכולת' }).selectOption({ label: 'תמלול' });
    await form.getByRole('textbox', { name: 'שפה' }).fill(lang);
    await form.getByRole('textbox', { name: 'מזהה הספק (חובה)' }).fill('openai');
    const modelField = form.getByRole('textbox', { name: 'מזהה המודל (חובה)' });
    await modelField.fill(model);
    await form.getByRole('button', { name: 'שמירת גרסה חדשה' }).click();

    // Источник: FL-39 «שינוי תצורה שאינו תקין נחסם לפני השמירה»; факт 04.11 — текст у поля.
    const error = form.getByText(`המודל «${model}» אינו מוכר בשרת עבור הספק «openai»`, { exact: false });
    await expect(error).toBeVisible();
    await expect(error).toContainText('מודלים זמינים:');
    await expect(page.getByText('נשמרה גרסה חדשה', { exact: true })).toHaveCount(0);
    expect(saves, 'форма отправила сохранение неизвестной модели').toEqual([]);
    await expect(modelField).toHaveValue(model);

    // Версия не появилась.
    const after = await listConfigs(api);
    expect(after.filter((c) => c.language === lang)).toEqual([]);
  });

  test(`FL-39 сервер: admin_set_provider_config с неизвестной моделью → 400 unknown_model, версия не создана @desktop ${TAG}`, async ({ page }) => {
    const api = await openWithApi(page, '/admin/providers');
    const lang = unusedLang(await listConfigs(api));
    expect(FORBIDDEN_LANGS).not.toContain(lang);
    const model = `qa-auto-e8e2be-${runStamp()}-nonexistent`;

    const res = await api.rpc('admin_set_provider_config', {
      p_capability: 'transcription',
      p_language: lang,
      p_provider: 'soniox',
      p_model: model,
      p_settings: {},
    });
    // Источник: ответ программиста 02.11 (unknown_model, ничего не сохраняется); факт 04.11 — RPC 400.
    if (res.ok()) test.info().annotations.push({ type: 'test-data', description: `ОШИБКА: сохранена версия transcription/${lang} ${model} — неудаляема, сделать неактивной вручную` });
    expect(res.status(), await res.text()).toBe(400);
    expect(await res.text()).toContain('unknown_model');
    expect((await listConfigs(api)).filter((c) => c.language === lang)).toEqual([]);
  });
});
